function makeEnv() {
  const log = [];
  const node = (id, extra = {}) => ({ id, value: '', innerHTML: '', hidden: false, disabled: false, required: false, checked: false, indeterminate: false, ...extra });
  const fieldNames = ['id', 'company_id', 'unit_id', 'employee_id_code', 'cpf', 'name', 'email', 'whatsapp', 'preferred_contact_channel',
    'sector', 'role_name', 'schedule_type', 'admission_date', 'tipo_vinculo', 'empresa_origem'];
  const elements = Object.fromEntries(fieldNames.map((n) => [n, node(`f:${n}`)]));
  const ids = ['employee-company', 'employee-unit', 'employee-legal-entity', 'employee-legal-entity-field', 'employee-tipo-vinculo', 'employee-empresa-origem-row'];
  const nodes = Object.fromEntries(ids.map((id) => [id, node(id)]));
  const refNames = ['employeesFilterCompany', 'employeesFilterUnit', 'employeesFilterSearch', 'employeesFilterSector', 'employeesFilterRole',
    'employeesOpsFilterCompany', 'employeesOpsFilterUnit', 'employeesOpsFilterSearch', 'employeesOpsFilterSector', 'employeesOpsFilterRole',
    'employeesBulkBar', 'employeesSelectAll'];
  const refs = Object.fromEntries(refNames.map((n) => [n, node(n)]));
  const bulkIds = new Set();
  const bulk = {
    has: (id) => bulkIds.has(id), count: () => bulkIds.size, ids: () => [...bulkIds],
    pageState: (pageIds) => { log.push(['pageState', pageIds]); const hit = pageIds.filter((i) => bulkIds.has(i)).length; return hit === 0 ? 'none' : hit === pageIds.length ? 'all' : 'some'; }
  };
  const state = {
    user: { id: 7, role: 'admin', company_id: 901 },
    employeesFilters: { company_id: '', unit_id: '', search: '', sector: '', role_name: '' },
    employeesOpsFilters: { company_id: '', unit_id: '', search: '', sector: '', role_name: '' },
    pagination: { employees: 4 },
    units: [{ id: 5, company_id: 901, name: 'Base', unit_type: 'base' }, { id: 6, company_id: 901, name: 'Navio', unit_type: 'navio' }, { id: 8, company_id: 902, name: 'Outra', unit_type: 'base' }],
    users: [{ id: 30, role: 'employee', employee_access_token: 'tok 1' }, { id: 31, role: 'employee' }, { id: 32, role: 'admin', employee_access_token: 'x' }],
    employees: [
      { id: 1, company_id: 901, company_name: 'Alfa', employee_id_code: 'M1', name: 'Ana Souza', cpf: '111', email: 'a@x', whatsapp: '119', preferred_contact_channel: 'email', sector: 'Convés', role_name: 'Marinheira', tipo_vinculo: 'CLT', unit_id: 5, unit_name: 'Base', unit_allocation_type: 'fixed', legal_entity_id: 44, schedule_type: '28x28', admission_date: '2024-01-02' },
      { id: 2, company_id: 901, company_name: 'Alfa', employee_id_code: 'M2', name: 'Bruno "B" Lima', sector: 'Máquinas', role_name: 'Mecânico', tipo_vinculo: 'Terceirizado', empresa_origem: 'Origem SA', current_unit_id: 6, current_unit_name: 'Navio', unit_id: 5 },
      { id: 3, company_id: 902, company_name: 'Beta', employee_id_code: 'M3', name: 'Caio', sector: 'Cozinha', role_name: 'Cozinheiro', tipo_vinculo: null, unit_id: 8, unit_name: 'Outra', whatsapp: '', email: '' }
    ]
  };
  const env = {
    log, nodes, elements, refs, state, bulkIds, popupOk: true, apiFails: null, noForm: false, bulkAvailable: true,
    globals: {
      Promise, JSON, Object, Array, String, Number, Error, Set, Boolean, encodeURIComponent,
      location: { origin: 'https://epi.test' },
      console: { warn: (...a) => log.push(['warn', String(a[0])]) },
      navigator: { clipboard: { writeText: async (t) => { log.push(['clipboard', t]); if (env.clipFails) { throw new Error('negado'); } } } },
      document: {
        getElementById: (id) => (id === 'employee-form' ? (env.noForm ? null : { elements }) : nodes[id] || null),
        createElement: (tag) => { const a = { tag, href: '', download: '', click() { log.push(['click', a.href, a.download]); } }; return a; }
      },
      Blob: function Blob(parts, opts) { log.push(['Blob', parts.join(''), opts.type]); this.parts = parts; },
      URL: { createObjectURL: () => 'blob:1', revokeObjectURL: (h) => log.push(['revoke', h]) },
      tr: (k, f) => `${k}|${f}`,
      alert: (m) => log.push(['alert', m]),
      populateSearchSelect: (field, items, labelFn, value) => { log.push(['populateSearchSelect', field.id, items.map(labelFn), value]); field.value = value === '6' ? '' : value; },
      unitsForSearchByCompany: (companyId) => state.units.filter((u) => !companyId || String(u.company_id) === String(companyId)),
      renderTables: () => log.push(['renderTables']),
      openAndPrintPopup: (html, feat) => { log.push(['popup', html, feat]); return env.popupOk; },
      qrCodeImageUrl: (l) => `QR(${l})`,
      filterByUserCompany: (items) => (items || []).filter((i) => i.company_id === 901),
      allocationTypeLabel: (v) => `AL(${v})`,
      employmentTypeLabel: (v) => `EMP(${v})`,
      isContractedVinculoJs: (v) => ['Terceirizado', 'Prestador de Serviço', 'Temporário'].includes(String(v || '').trim()),
      unitTypeLabel: (t) => `T(${t})`,
      legalEntitiesForCompany: (cid) => (String(cid) === '901' ? [{ id: 44 }, { id: 45 }] : String(cid) === '902' ? [{ id: 46 }] : []),
      legalEntityHelpers: () => (env.noRequiredHelper ? {} : { employeeLegalEntityRequired: (list) => list.length > 1 }),
      legalEntityOptionsHtml: (list) => list.map((e) => `<option value="${e.id}">${e.id}</option>`).join(''),
      setFormSubmitLabel: (id, t) => log.push(['submitLabel', id, t]),
      showView: (v) => log.push(['showView', v]),
      focusRegistrationTab: (v) => log.push(['focusTab', v]),
      hasPermission: () => true, canAccessView: () => true,
      dsCreateBulkSelection: () => (env.bulkAvailable ? bulk : null),
      dsBulkBar: (count, actions, opts) => `BAR(${count},${actions.map((a) => a.id + ':' + a.label).join('/')},${opts.labelPlural},${opts.labelSingular},${opts.clearLabel})`,
      api: async (p, o) => { log.push(['api', p, o.method, o.body]); if (env.apiFails) { throw new Error(env.apiFails); } return env.apiPayload || { token: 'tk' }; }
    }
  };
  return env;
}

function contextFor(env) {
  const ctx = vm.createContext({ ...env.globals, __EPI_APP_STATE__: env.state, __EPI_REFS__: env.refs });
  ctx.globalThis = ctx;
  return ctx;
}

function snapshot(env) {
  const pick = (o) => Object.fromEntries(Object.entries(o).filter(([, n]) => n).map(([k, n]) => [k, [n.value, n.innerHTML, n.hidden, n.disabled, n.required, n.checked, n.indeterminate]]));
  return { nodes: pick(env.nodes), form: pick(env.elements), refs: pick(env.refs), filters: [env.state.employeesFilters, env.state.employeesOpsFilters, env.state.pagination], log: env.log.splice(0) };
}

async function scenario(run) {
  const out = {};
  const go = async (prep, act) => {
    const env = makeEnv(); prep(env); const f = run(env);
    let r;
    try { r = await act(f, env); } catch (error) { r = { thrown: `${error.name}: ${error.message}` }; }
    return { r: r === undefined ? null : r, ...snapshot(env) };
  };
  const none = () => {};
  const E = (env, i) => env.state.employees[i];

  out.link = await go(none, (f) => [f.buildEmployeeAccessLink(' ab c/1 '), f.buildEmployeeAccessLink(''), f.buildEmployeeAccessLink(null)]);
  out.filtrosCadastro = await go((env) => {
    Object.assign(env.refs.employeesFilterCompany, { value: ' 901 ' }); Object.assign(env.refs.employeesFilterUnit, { value: '6' });
    Object.assign(env.refs.employeesFilterSearch, { value: ' ANA ' }); Object.assign(env.refs.employeesFilterSector, { value: 'Convés ' });
    Object.assign(env.refs.employeesFilterRole, { value: ' MAR' });
  }, (f) => f.syncEmployeesSearchFilters());
  out.filtrosOps = await go((env) => { Object.assign(env.refs.employeesOpsFilterCompany, { value: '902' }); Object.assign(env.refs.employeesOpsFilterUnit, { value: '8' }); },
    (f) => f.syncEmployeesSearchFilters('ops'));
  out.filtrosSemCampos = await go((env) => { for (const k of Object.keys(env.refs)) { if (k.startsWith('employeesFilter')) { delete env.refs[k]; } } env.refs.employeesFilterUnit = undefined; env.state.pagination = null; },
    (f) => f.syncEmployeesSearchFilters('employees'));
  out.filtragem = await go(none, (f, env) => [
    {}, { company_id: '901' }, { unit_id: '6' }, { unit_id: '5' }, { search: 'm3' }, { search: '2' }, { sector: 'máq' }, { role_name: 'cozinh' }, { search: 'zzz' }
  ].map((partial) => { env.state.employeesFilters = { company_id: '', unit_id: '', search: '', sector: '', role_name: '', ...partial }; env.state.employeesOpsFilters = { ...env.state.employeesFilters, company_id: '902' }; return [f.applyEmployeesFilters(env.state.employees).map((e) => e.id), f.applyEmployeesFilters(env.state.employees, 'ops').map((e) => e.id)]; }));
  out.busca = await go(none, (f, env) => [f.matchesEmployeeSearchText(E(env, 0), ''), f.matchesEmployeeSearchText(E(env, 0), ' souza '), f.matchesEmployeeSearchText({}, 'x'), f.matchesEmployeeSearchText({ id: 12 }, '12')]);
  out.vinculoProprio = await go(none, (f) => ['CLT', ' Estagiário ', 'Menor Aprendiz', 'Praticante', '', null, 'Terceirizado', 'clt'].map((v) => f.isOwnWorkforceVinculo(v)));
  out.botoesFuncionario = await go(none, (f, env) => env.state.users.map((u) => { const a = []; f.addEmployeeButtons(a, u); return a; }));
  out.linhas = await go((env) => { env.bulkIds.add(2); }, (f, env) => [f.buildEmployeeRow(E(env, 0), true), f.buildEmployeeRow(E(env, 1), false), f.buildEmployeeRow(E(env, 2), true), f.buildEmployeeOpsRow(E(env, 1)), f.buildEmployeeOpsRow(E(env, 2))]);
  out.linhasSemLote = await go((env) => { env.bulkAvailable = false; }, (f, env) => f.buildEmployeeRow(E(env, 0), true));
  out.escopoLote = await go((env) => { env.state.employeesFilters.search = 'bruno'; }, (f) => f.currentEmployeesBulkScope().map((e) => e.id));
  out.csv = await go((env) => { env.bulkIds.add(2); env.bulkIds.add(1); env.bulkIds.add(3); }, (f) => f.exportSelectedEmployeesCsv());
  out.csvVazio = await go(none, (f) => f.exportSelectedEmployeesCsv());
  out.csvForaDoEscopo = await go((env) => { env.bulkIds.add(3); }, (f) => f.exportSelectedEmployeesCsv());
  out.csvSemLote = await go((env) => { env.bulkAvailable = false; }, (f) => f.exportSelectedEmployeesCsv());
  out.barra = await go((env) => { env.bulkIds.add(1); }, (f) => { f.renderEmployeesBulkUi([1, 2]); });
  out.barraTodos = await go((env) => { env.bulkIds.add(1); env.bulkIds.add(2); }, (f) => { f.renderEmployeesBulkUi([1, 2]); });
  out.barraSemSelecionarTodos = await go((env) => { delete env.refs.employeesSelectAll; }, (f) => { f.renderEmployeesBulkUi([]); });
  out.barraSemRef = await go((env) => { delete env.refs.employeesBulkBar; }, (f) => { f.renderEmployeesBulkUi([1]); });
  out.empresaOrigem = await go(none, (f, env) => ['CLT', 'Terceirizado', 'Estagiário', ''].map((v) => { env.nodes['employee-tipo-vinculo'].value = v; f.syncEmpresaOrigemVisibility(); return env.nodes['employee-empresa-origem-row'].hidden; }));
  out.empresaOrigemSemCampos = await go((env) => { delete env.nodes['employee-tipo-vinculo']; delete env.nodes['employee-empresa-origem-row']; }, (f) => f.syncEmpresaOrigemVisibility());
  out.unidades = await go((env) => { env.nodes['employee-company'].value = '901'; env.nodes['employee-unit'].value = '99'; env.nodes['employee-legal-entity'].value = '45'; }, (f) => f.syncEmployeeUnitOptions());
  out.unidadesMantem = await go((env) => { env.nodes['employee-unit'].value = '6'; }, (f) => f.syncEmployeeUnitOptions());
  out.unidadesSemCampo = await go((env) => { delete env.nodes['employee-unit']; }, (f) => f.syncEmployeeUnitOptions());
  out.cnpjUnico = await go((env) => { env.nodes['employee-company'].value = '902'; }, (f) => f.syncEmployeeLegalEntityOptions());
  out.cnpjSemHelper = await go((env) => { env.noRequiredHelper = true; env.nodes['employee-legal-entity'].value = '99'; }, (f) => f.syncEmployeeLegalEntityOptions());
  out.cnpjSemEmpresa = await go((env) => { env.state.user.company_id = null; }, (f) => f.syncEmployeeLegalEntityOptions());
  out.cnpjTrava = await go(none, (f) => { f.setEmployeeLegalEntityLock(45, true); });
  out.cnpjDestrava = await go(none, (f) => { f.setEmployeeLegalEntityLock('', false); });
  out.editar = await go(none, (f) => f.startEditEmployee('1'));
  out.editarPadroes = await go(none, (f) => f.startEditEmployee(3));
  out.editarSemForm = await go((env) => { env.noForm = true; }, (f) => f.startEditEmployee(1));
  out.editarInexistente = await go(none, (f) => f.startEditEmployee(99));
  out.qr = await go(none, (f) => [f.printEmployeeAccessQr('30'), f.printEmployeeAccessQr(31), f.printEmployeeAccessQr(99)]);
  out.qrBloqueado = await go((env) => { env.popupOk = false; }, (f) => f.printEmployeeAccessQr(30));
  out.portal = await go((env) => { env.apiPayload = { access_link: 'https://l/1' }; }, (f) => f.printEmployeePortalLink('2'));
  out.portalQrValue = await go((env) => { env.apiPayload = { qr_code_value: 'qrv', token: 'zz' }; }, (f) => f.printEmployeePortalLink(99));
  out.portalToken = await go((env) => { env.popupOk = false; env.apiPayload = { token: 'tt' }; }, (f) => f.printEmployeePortalLink(1));
  out.portalErro = await go((env) => { env.apiFails = 'Sem permissão.'; }, (f) => f.printEmployeePortalLink(1));
  out.portalSemAtor = await go((env) => { env.state.user = null; }, (f) => f.printEmployeePortalLink(1));
  out.sucesso = await go(none, (f) => f.handleEmployeeFormSuccess('https://l/2'));
  out.sucessoSemClipboard = await go((env) => { env.clipFails = true; }, (f) => f.handleEmployeeFormSuccess('https://l/3'));
  return out;
}

