function loadModules(env) {
  const ctx = contextFor(env);
  for (const rel of MODULES) { vm.runInContext(fs.readFileSync(path.join(JS_ROOT, rel), 'utf8'), ctx); }
  return ctx;
}

// Roda as funções originais como no app.js: dentro de um bloco, com as
// constantes de bloco de que dependem, publicando só os nomes pedidos.
function runAppSlices(ctx, appSource, names) {
  const lines = appSource.split('\n');
  const slice = (n) => {
    const s = lines.findIndex((l) => l.startsWith(`function ${n}(`) || l.startsWith(`async function ${n}(`));
    if (s < 0) { throw new Error(`não achei ${n}`); }
    let e = s;
    while (!/^}/.test(lines[e])) { e++; }
    return lines.slice(s, e + 1).join('\n');
  };
  const consts = [
    lines.find((l) => l.startsWith('const employeesBulk = ')),
    lines.find((l) => l.startsWith('const OWN_WORKFORCE_VINCULOS = '))
  ];
  if (consts.some((c) => !c)) { throw new Error('constantes de bloco não encontradas'); }
  vm.runInContext(`{ const state = globalThis.__EPI_APP_STATE__; const refs = globalThis.__EPI_REFS__;\n${consts.join('\n')}\n`
    + `${names.map(slice).join('\n')}\n${names.map((n) => `globalThis.${n} = ${n};`).join(' ')} }`, ctx);
  return ctx;
}

// FIX-COLAB-TERC-V1 intentional differences from the frozen V4 table:
// navigation precedes hydration, edit focuses Cadastro, foreign rows deny.
EXPECTED.editar.log = [['showView', 'colaboradores'], ['submitLabel', 'employee-form', 'Atualizar colaborador'], ['focusTab', 'colaboradores']];
EXPECTED.editarPadroes = EXPECTED.editarInexistente;

module.exports = function ({ testAsync, test, assert, eq }) {
  testAsync('UBX-V4 Colaboradores: os módulos reproduzem as funções originais', async () => {
    const actual = await scenario(loadModules);
    for (const key of Object.keys(EXPECTED)) {
      const expected = JSON.parse(JSON.stringify(EXPECTED[key]));
      if (key === 'editar') {
        expected.form.company_id[0] = String(expected.form.company_id[0]);
        expected.form.unit_id[0] = String(expected.form.unit_id[0]);
      }
      eq(JSON.stringify(actual[key]), JSON.stringify(expected), key);
    }
    eq(Object.keys(actual).sort().join(','), Object.keys(EXPECTED).sort().join(','));
  });

  test('UBX-V4 Colaboradores: negócio puro, globais, namespaces, lote único e ordem de carga', () => {
    const env = makeEnv();
    const ctx = loadModules(env);
    for (const name of [...UI, ...BUSINESS]) { eq(typeof ctx[name], 'function', name); }
    for (const ns of ['__EPI_EMPLOYEES_VIEW__', '__EPI_EMPLOYEES_BUSINESS__', '__EPI_EMPLOYEES_API__']) { assert(Object.isFrozen(ctx[ns]), `${ns} congelado`); }
    const b = ctx.__EPI_EMPLOYEES_BUSINESS__;
    eq(b.OWN_WORKFORCE_VINCULOS.join(','), 'CLT,Menor Aprendiz,Praticante,Estagiário');
    eq(JSON.stringify(b.filterEmployees([{ id: 1, company_id: 2 }, { id: 2, company_id: 3 }], { company_id: '3' }).map((e) => e.id)), '[2]');
    eq(b.employeesCsv([{ name: 'a"b', tipo_vinculo: 'X' }], (v) => `L(${v})`).split('\n')[1], '"";"";"a""b";"";"";"";"";"";"L(X)";""');
    assert(ctx.__EPI_EMPLOYEES_VIEW__.employeesBulk === ctx.dsCreateBulkSelection(), 'expõe a instância de lote criada no carregamento');
    const scripts = fs.readFileSync(path.resolve(JS_ROOT, '..', 'views', '_scripts.html'), 'utf8');
    const order = [...scripts.matchAll(/<script[^>]+src="([^"?]+)/g)].map((m) => m[1]);
    const idx = MODULES.map((m) => order.indexOf(`/js/${m}`));
    assert(idx.every((i) => i >= 0) && idx[0] < idx[1] && idx[1] < idx[2], 'negócio → integração → UI');
    assert(idx[2] < order.indexOf('/app.js'), 'antes do app.js');
    assert(order.indexOf('/js/views/ui-helpers.js') < idx[2], 'ui-helpers (dsCreateBulkSelection) antes da UI: o lote nasce no carregamento');
    assert(order.indexOf('/js/modules/api-client.js') < idx[1], 'api-client antes da integração');
    const app = fs.readFileSync(path.resolve(JS_ROOT, '..', 'app.js'), 'utf8');
    for (const name of [...UI, ...BUSINESS]) {
      assert(!new RegExp(`^(?:async\\s+)?function\\s+${name}\\(`, 'm').test(app), `${name} voltou ao app.js`);
    }
    assert(app.includes('const employeesBulk = globalThis.__EPI_EMPLOYEES_VIEW__ ? globalThis.__EPI_EMPLOYEES_VIEW__.employeesBulk : null;'),
      'o app.js lê a MESMA instância de seleção em lote');
    assert(!/^const OWN_WORKFORCE_VINCULOS/m.test(app), 'OWN_WORKFORCE_VINCULOS saiu do app.js');
  });
};

module.exports.scenario = scenario;
module.exports.contextFor = contextFor;
module.exports.runAppSlices = runAppSlices;
